<?php require_once __DIR__.'/../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$qty=(int)$_POST['quantity'];$reason=trim($_POST['reason']??'Manual adjustment');$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$s->execute([$id]);$p=$s->fetch();if(!$p)throw new Exception('Product not found');$new=max(0,(int)$p['stock']+$qty);$diff=$new-(int)$p['stock'];$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO inventory_movements(product_id,change_qty,reason) VALUES(?,?,?)')->execute([$id,$diff,$reason]);$pdo->commit();flash('Inventory updated.');}catch(Throwable $e){$pdo->rollBack();flash('Could not update inventory.','error');}header('Location: /powervault/admin/inventory.php');exit;}$products=db()->query('SELECT * FROM products ORDER BY name')->fetchAll();$moves=db()->query('SELECT m.*,p.name FROM inventory_movements m JOIN products p ON p.id=m.product_id ORDER BY m.id DESC LIMIT 30')->fetchAll();$pageTitle='Inventory';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container-fluid admin-layout"><aside class="admin-sidebar"><div class="eyebrow">CONTROL CENTER</div><a href="/powervault/admin/">▦ Dashboard</a><a href="/powervault/admin/products.php">◇ Products</a><a class="active" href="/powervault/admin/inventory.php">▤ Inventory</a><a href="/powervault/admin/orders.php">⇄ Orders</a><a href="/powervault/admin/profit-loss.php">⌁ Profit & Loss</a><a href="/powervault/admin/settings.php">⚙ Settings</a><a href="/powervault/logout.php">↪ Logout</a></aside><div class="admin-content"><div class="eyebrow">STOCK CONTROL</div><h1>Inventory <span class="gradient-text">Management</span></h1><div class="dashboard-panel mt-4"><h3>Adjust Stock</h3><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-5"><label class="form-label">Product</label><select class="form-select" name="id"><?php foreach($products as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> (current: <?=$p['stock']?>)</option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Change Quantity (+/-)</label><input type="number" class="form-control" name="quantity" required></div><div class="col-md-4"><label class="form-label">Reason</label><input class="form-control" name="reason" value="Manual adjustment"></div><div class="col-12"><button class="btn btn-neon">Update Stock</button></div></form></div><div class="dashboard-panel mt-4"><h3>Current Stock</h3><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Product</th><th>Stock</th><th>Indicator</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=e($p['name'])?></td><td><?=$p['stock']?></td><td><?=$p['stock']<5?'<span class="status-pill warning">Low stock</span>':'<span class="status-pill">In stock</span>'?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="dashboard-panel mt-4"><h3>Recent Movements</h3><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Product</th><th>Change</th><th>Reason</th><th>Date</th></tr></thead><tbody><?php foreach($moves as $m): ?><tr><td><?=e($m['name'])?></td><td><?=((int)$m['change_qty']>0?'+':'').(int)$m['change_qty']?></td><td><?=e($m['reason'])?></td><td><?=e($m['created_at'])?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
